import itertools

def is_valid(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check max independent set <= 3
    # This means no independent set of size 4
    for subset in itertools.combinations(range(n), 4):
        is_indep = True
        for u, v in itertools.combinations(subset, 2):
            if v in adj[u]:
                is_indep = False
                break
        if is_indep:
            print("Failed: found independent set of size 4")
            return False

    # Check vertex connectivity >= 4
    # This means removing any 3 vertices leaves the graph connected
    for subset in itertools.combinations(range(n), 3):
        remaining = set(range(n)) - set(subset)
        start = next(iter(remaining))
        visited = set([start])
        queue = [start]
        while queue:
            curr = queue.pop(0)
            for neighbor in adj[curr]:
                if neighbor in remaining and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        if len(visited) < len(remaining):
            print("Failed: removing 3 vertices disconnects the graph")
            return False

    return True

edges = list(itertools.combinations(range(20), 2))
print("K_20 valid:", is_valid(edges, 20))
